module magic_checkerboard (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] board_0, board_1, board_2, board_3,\n    input wire [7:0] board_4, board_5, board_6, board_7,\n    input wire [7:0] board_8, board_9, board_10, board_11,\n    input wire [7:0] board_12, board_13, board_14, board_15,\n    output reg [15:0] result,\n    output reg done\n);\n\n    localparam [2:0] IDLE        = 3'd0;\n    localparam [2:0] SETUP_COMBO = 3'd1;\n    localparam [2:0] PROCESS_CELL= 3'd2;\n    localparam [2:0] CHECK_COMBO = 3'd3;\n    localparam [2:0] NEXT_COMBO  = 3'd4;\n    localparam [2:0] DONE_STATE  = 3'd5;\n\n    reg [2:0] state;\n    reg [7:0] board_reg [0:15];\n    reg [7:0] filled_reg [0:15];\n    reg [3:0] cell_idx;\n    reg [1:0] combo_idx;\n    reg [15:0] min_sum;\n    reg [15:0] current_sum;\n    reg combo_valid;\n    integer i;  // Loop variable\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 16'hFFFF;\n            cell_idx <= 4'd0;\n            combo_idx <= 2'd0;\n            min_sum <= 16'hFFFF;\n            current_sum <= 16'd0;\n            combo_valid <= 1'b1;\n            for (i = 0; i < 16; i = i + 1) begin\n                board_reg[i] <= 8'd0;\n                filled_reg[i] <= 8'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    result <= 16'hFFFF;\n                    if (start) begin\n                        // Load input board element-by-element\n                        board_reg[0]  <= board_0;  board_reg[1]  <= board_1;\n                        board_reg[2]  <= board_2;  board_reg[3]  <= board_3;\n                        board_reg[4]  <= board_4;  board_reg[5]  <= board_5;\n                        board_reg[6]  <= board_6;  board_reg[7]  <= board_7;\n                        board_reg[8]  <= board_8;  board_reg[9]  <= board_9;\n                        board_reg[10] <= board_10; board_reg[11] <= board_11;\n                        board_reg[12] <= board_12; board_reg[13] <= board_13;\n                        board_reg[14] <= board_14; board_reg[15] <= board_15;\n\n                        state <= SETUP_COMBO;\n                        combo_idx <= 2'd0;\n                        min_sum <= 16'hFFFF;\n                    end\n                end\n\n                SETUP_COMBO: begin\n                    current_sum <= 16'd0;\n                    cell_idx <= 4'd0;\n                    combo_valid <= 1'b1;\n                    // Copy board_reg to filled_reg\n                    for (i = 0; i < 16; i = i + 1) begin\n                        filled_reg[i] <= board_reg[i];\n                    end\n                    state <= PROCESS_CELL;\n                end\n\n                PROCESS_CELL: begin\n                    if (combo_valid) begin\n                        // Combinational calculation of constraints\n                        reg [3:0] row = cell_idx[3:2];\n                        reg [3:0] col = cell_idx[1:0];\n                        reg [7:0] left_val = (col > 0) ? filled_reg[cell_idx-1] : 8'd0;\n                        reg [7:0] top_val = (row > 0) ? filled_reg[cell_idx-4] : 8'd0;\n                        reg [7:0] lower_bound = (left_val >= top_val) ? left_val + 8'd1 : top_val + 8'd1;\n                        if (lower_bound < left_val) lower_bound = left_val + 8'd1;  // Overflow check\n                        if (lower_bound < top_val) lower_bound = top_val + 8'd1;\n\n                        // Parity calculation\n                        reg req_parity;\n                        if ((row + col) % 2 == 0) begin\n                            req_parity = (row % 2) ? ~combo_idx[0] : combo_idx[0];\n                        end else begin\n                            req_parity = (row % 2) ? ~combo_idx[1] : combo_idx[1];\n                        end\n\n                        if (board_reg[cell_idx] != 0) begin\n                            // Check existing cell\n                            if (board_reg[cell_idx] < lower_bound || \n                                board_reg[cell_idx][0] != req_parity) \n                                combo_valid <= 1'b0;\n                            else\n                                current_sum <= current_sum + board_reg[cell_idx];\n                        end else begin\n                            // Fill zero cell\n                            reg [7:0] new_val = (lower_bound[0] == req_parity) ? lower_bound : lower_bound + 8'd1;\n                            if (new_val > 8'd255) begin\n                                combo_valid <= 1'b0;\n                            end else begin\n                                filled_reg[cell_idx] <= new_val;\n                                current_sum <= current_sum + new_val;\n                            end\n                        end\n                    end\n\n                    if (cell_idx == 4'd15) begin\n                        state <= CHECK_COMBO;\n                    end else begin\n                        cell_idx <= cell_idx + 4'd1;\n                    end\n                end\n\n                CHECK_COMBO: begin\n                    if (combo_valid && (current_sum < min_sum)) begin\n                        min_sum <= current_sum;\n                    end\n                    state <= NEXT_COMBO;\n                end\n\n                NEXT_COMBO: begin\n                    if (combo_idx == 2'd3) begin\n                        state <= DONE_STATE;\n                    end else begin\n                        combo_idx <= combo_idx + 2'd1;\n                        state <= SETUP_COMBO;\n                    end\n                end\n\n                DONE_STATE: begin\n                    result <= min_sum;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule